const data = $input.first().json;
if (!data || data.error || !data.ok || !data.connected || !data.playing || !data.track || !data.track.id) {
  return [];
}

const track = data.track;
const progressMs = Number(data.progressMs || 0);
const durationMs = Number(track.durationMs || 0);

// Regra estilo Last.fm: só faz scrobble após 20s (ou em faixas curtas <40s)
if (durationMs >= 40000 && progressMs < 20000) {
  return [];
}

const state = $getWorkflowStaticData('global');
const nowMs = Date.now();
const minCooldownMs = Math.max(30000, Math.round((durationMs || 180000) * 0.5));
const sameTrack = state.lastTrackId === track.id;
const restarted = sameTrack && Number.isFinite(state.lastProgressMs) && progressMs + 15000 < state.lastProgressMs;

if (sameTrack && !restarted && (nowMs - Number(state.lastScrobbleAt || 0)) < minCooldownMs) {
  state.lastProgressMs = progressMs;
  return [];
}

state.lastTrackId = track.id;
state.lastProgressMs = progressMs;
state.lastScrobbleAt = nowMs;

const record = {
  playedAt: new Date(nowMs).toISOString(),
  trackId: String(track.id),
  trackUri: track.uri ? String(track.uri) : null,
  trackName: String(track.name || 'Faixa desconhecida').slice(0, 250),
  artists: Array.isArray(track.artists) ? track.artists.map(a => String(a).slice(0, 120)) : [],
  album: track.album ? String(track.album).slice(0, 250) : null,
  durationMs: Number.isFinite(durationMs) && durationMs > 0 ? Math.round(durationMs) : null,
  progressMs: Number.isFinite(progressMs) ? Math.round(progressMs) : 0,
  deviceName: data.device && data.device.name ? String(data.device.name).slice(0, 120) : null
};

return [{
  json: {
    record,
    payloadB64: Buffer.from(JSON.stringify(record), 'utf8').toString('base64')
  }
}];
